-- msa-clientes

\set ON_ERROR_STOP on

\connect postgres banco postgres-clientes 5432

SELECT 'CREATE DATABASE clientes_db'
WHERE NOT EXISTS (SELECT FROM pg_database WHERE datname = 'clientes_db')\gexec

\connect clientes_db banco postgres-clientes 5432

-- Persona
CREATE TABLE IF NOT EXISTS persona (
    id             BIGINT       GENERATED BY DEFAULT AS IDENTITY,
    tipo_persona   VARCHAR(20)  NOT NULL,
    nombre         VARCHAR(120) NOT NULL,
    genero         VARCHAR(20),
    edad           INTEGER,
    identificacion VARCHAR(30)  NOT NULL,
    direccion      VARCHAR(200),
    telefono       VARCHAR(30),
    CONSTRAINT persona_pkey PRIMARY KEY (id),
    CONSTRAINT uk_persona_identificacion UNIQUE (identificacion),
    CONSTRAINT ck_persona_genero CHECK (genero IN ('MASCULINO', 'FEMENINO', 'OTRO')),
    CONSTRAINT ck_persona_tipo_persona CHECK (tipo_persona = 'CLIENTE')
);

-- Cliente
CREATE TABLE IF NOT EXISTS cliente (
    id            BIGINT       NOT NULL,
    cliente_id    VARCHAR(20)  NOT NULL,
    password_hash VARCHAR(100) NOT NULL,
    estado        VARCHAR(20)  NOT NULL,
    fecha_alta    TIMESTAMP(6) NOT NULL,
    CONSTRAINT cliente_pkey PRIMARY KEY (id),
    CONSTRAINT uk_cliente_cliente_id UNIQUE (cliente_id),
    CONSTRAINT fk_cliente_persona FOREIGN KEY (id) REFERENCES persona (id),
    CONSTRAINT ck_cliente_estado CHECK (estado IN ('ACTIVO', 'INACTIVO'))
);


-- msa-cuentas

\connect postgres banco postgres-cuentas 5432

SELECT 'CREATE DATABASE cuentas_db'
WHERE NOT EXISTS (SELECT FROM pg_database WHERE datname = 'cuentas_db')\gexec

\connect cuentas_db banco postgres-cuentas 5432

-- Secuencia para cuenta.id
CREATE SEQUENCE IF NOT EXISTS cuenta_id_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1;

-- Cuenta
CREATE TABLE IF NOT EXISTS cuenta (
    id             BIGINT        NOT NULL DEFAULT nextval('cuenta_id_seq'),
    version        BIGINT        NOT NULL,
    numero_cuenta  VARCHAR(20)   NOT NULL,
    tipo_cuenta    VARCHAR(20)   NOT NULL,
    saldo_inicial  NUMERIC(19,2) NOT NULL,
    saldo_actual   NUMERIC(19,2) NOT NULL,
    estado         VARCHAR(20)   NOT NULL,
    cliente_id     VARCHAR(20)   NOT NULL,
    nombre_cliente VARCHAR(120)  NOT NULL,
    identificacion VARCHAR(30),
    CONSTRAINT cuenta_pkey PRIMARY KEY (id),
    CONSTRAINT uk_cuenta_numero_cuenta UNIQUE (numero_cuenta),
    CONSTRAINT ck_cuenta_estado CHECK (estado IN ('ACTIVA', 'INACTIVA', 'CERRADA')),
    CONSTRAINT ck_cuenta_tipo_cuenta CHECK (tipo_cuenta IN ('CORRIENTE', 'AHORRO'))
);

-- Asegura el DEFAULT de id si la tabla ya existia.
ALTER TABLE cuenta ALTER COLUMN id SET DEFAULT nextval('cuenta_id_seq');

-- Movimiento
CREATE TABLE IF NOT EXISTS movimiento (
    id              BIGINT        GENERATED BY DEFAULT AS IDENTITY,
    fecha           TIMESTAMP(6)  NOT NULL,
    tipo_movimiento VARCHAR(20)   NOT NULL,
    valor           NUMERIC(19,2) NOT NULL,
    saldo           NUMERIC(19,2) NOT NULL,
    referencia      VARCHAR(60),
    cuenta_id       BIGINT        NOT NULL,
    CONSTRAINT movimiento_pkey PRIMARY KEY (id),
    CONSTRAINT fk_movimiento_cuenta FOREIGN KEY (cuenta_id) REFERENCES cuenta (id),
    CONSTRAINT ck_movimiento_tipo_movimiento CHECK (tipo_movimiento IN ('INGRESO', 'EGRESO'))
);


